[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Release note packet missing: $rel"}
$p=([Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($full))|ConvertFrom-Json);foreach($f in @('schemaVersion','head','owner','changed','verified','blocked','unverified')){if([string]::IsNullOrWhiteSpace([string]$p.$f)-and @($p.$f).Count -eq 0){throw "Release note packet missing ${f}."}};if([string]$p.schemaVersion -ne '1'){throw 'Release note schemaVersion must be 1.'};if(@($p.blocked).Count -gt 0-and @($p.unverified).Count -eq 0){throw 'Blocked release note requires explicit unverified items.'}
Write-Output "PASS: evidence-linked release note packet is bounded: $rel"
